t = int(input())
for _ in range(t):
	(n, m) = map(int, input().split())
	(x, y, s) = map(int, input().split())
	if x > 0:
		xs = list(map(int, input().split()))
		xs = [0] + xs + [n + 1]
	else:
		xs = [0, n + 1]
	if y > 0:
		ys = list(map(int, input().split()))
		ys = [0] + ys + [m + 1]
	else:
		ys = [0, m + 1]
	hors = 0
	verts = 0
	for i in range(1, x + 2):
		space = xs[i] - xs[i - 1]
		if space > 0:
			space -= 1
		verts += space // s
	for j in range(1, y + 2):
		space = ys[j] - ys[j - 1]
		if space > 0:
			space -= 1
		hors += space // s
	print(hors * verts)
